float fit=(8.8f/glazing)/(1800f/(800*.68f));u.x=128+.5f+(old[i].x-128-.5f)*fit;}if(old[i].x>=127&&q.y<=glazing+.001f)q.y+=floorLevel;vertex(q,ns[i],u);}}
Action<Vector3,Vector3,Vector3,Vector3,Vector2,Vector2,Vector2,Vector2> quad=(a,c,d,e,ua,uc,ud,ue)=>{var normal=Vector3.Cross(c-a,d-a).normalized;foreach(var item in new[]{new KeyValuePair<Vector3,Vector2>(a,ua),new KeyValuePair<Vector3,Vector2>(c,uc),new KeyValuePair<Vector3,Vector2>(d,ud),new KeyValuePair<Vector3,Vector2>(a,ua),new KeyValuePair<Vector3,Vector2>(d,ud),new KeyValuePair<Vector3,Vector2>(e,ue)})vertex(item.Key,normal,item.Value);};
