float signWidth=Mathf.Min(8.8f,(top-glassTop)*(1800f/(800*.31f))),signLeft=(width-signWidth)*.5f,signRight=signLeft+signWidth,signHeight=signWidth/(1800f/(800*.31f)),mid=(top+glassTop)*.5f,y0=mid-signHeight*.5f,y1=mid+signHeight*.5f;quad(new Vector3(b.max.x-signLeft,y0,z+.015f),new Vector3(b.max.x-signLeft,y1,z+.015f),new Vector3(b.max.x-signRight,y1,z+.015f),new Vector3(b.max.x-signRight,y0,z+.015f),new Vector2(128,.69f),new Vector2(128,1),new Vector2(129,1),new Vector2(129,.69f));
