for(int step=1;step<=2;step++){float x0=b.center.x-1.5f,x1=b.center.x+1.5f,z0=apron+(step-1)*.36f,z1=z0+.36f,hi=floorLevel-rise*step,lo=middleGround-.04f;stone(new Vector3(x1,hi,z1),new Vector3(x1,hi,z0),new Vector3(x0,hi,z0),new Vector3(x0,hi,z1));stone(new Vector3(x1,lo,z1),new Vector3(x1,hi,z1),new Vector3(x0,hi,z1),new Vector3(x0,lo,z1));stone(new Vector3(x0,lo,z1),new Vector3(x0,hi,z1),new Vector3(x0,hi,z0),new Vector3(x0,lo,z0));stone(new Vector3(x1,lo,z0),new Vector3(x1,hi,z0),new Vector3(x1,hi,z1),new Vector3(x1,lo,z1));}
