var pp=new List<Vector3>();var nn=new List<Vector3>();var uu=new List<Vector2>();var tt=new List<int>();var welded=new Dictionary<string,int>();for(int i=0;i<p.Count;i++){string key=p[i].ToString("F6")+n[i].ToString("F6")+uv[i].ToString("F6");if(!welded.TryGetValue(key,out int index)){index=pp.Count;welded[key]=index;pp.Add(p[i]);nn.Add(n[i]);uu.Add(uv[i]);}tt.Add(index);}m.Clear();m.indexFormat=pp.Count>65535?UnityEngine.Rendering.IndexFormat.UInt32:UnityEngine.Rendering.IndexFormat.UInt16;m.SetVertices(pp);m.SetNormals(nn);m.SetUVs(0,uu);m.subMeshCount=1;m.SetTriangles(tt,0);m.RecalculateTangents();m.RecalculateBounds();m.name+=" Fit corrected";EditorUtility.SetDirty(m);f.GetComponent<Renderer>().sharedMaterials=new[]{material};total+=tt.Count/3;}
