var capture=typeof(CityTaxiStandBuild).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic);var controller=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CityDayNightController>(true)).FirstOrDefault();bool night=controller&&controller.IsNight;GameObject player=null;try{if(controller)controller.Apply(false);capture.Invoke(null,new object[]{sc,t.TransformPoint(new Vector3(-.25f,7.5f,39)),t.TransformPoint(new Vector3(-.25f,7.6f,10.5f)),"GunShop-Day"});capture.Invoke(null,new object[]{sc,t.TransformPoint(new Vector3(-.25f,4.4f,25)),t.TransformPoint(new Vector3(-.25f,3.5f,11)),"GunShop-Front"});capture.Invoke(null,new object[]{sc,t.TransformPoint(new Vector3(-11,7,27)),t.TransformPoint(new Vector3(-.25f,4.5f,10.5f)),"GunShop-Joins"});player=GameObject.CreatePrimitive(PrimitiveType.Capsule);player.hideFlags=HideFlags.HideAndDontSave;player.transform.SetParent(t,false);player.transform.localPosition=new Vector3(2,floorLevel+.9f,11.3f);player.transform.localScale=new Vector3(.55f,.9f,.55f);capture.Invoke(null,new object[]{sc,t.TransformPoint(new Vector3(-.25f,3.2f,23)),t.TransformPoint(new Vector3(-.25f,2.1f,11)),"GunShop-PlayerScale"});UnityEngine.Object.DestroyImmediate(player);player=null;if(controller)controller.Apply(true);capture.Invoke(null,new object[]{sc,t.TransformPoint(new Vector3(-.25f,7.5f,37)),t.TransformPoint(new Vector3(-.25f,7.6f,10.5f)),"GunShop-Night"});}finally{if(player)UnityEngine.Object.DestroyImmediate(player);if(controller)controller.Apply(night);}if(t.GetComponentsInChildren<Renderer>(true).Any(r=>r.sharedMaterials.Length!=1||r.sharedMaterial!=material)||ShaderUtil.ShaderHasError(material.shader))throw new Exception("Material/shader check failed");AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(sc);EditorSceneManager.SaveScene(sc);File.WriteAllText("FinalEnvironmentRoadReview/GunShop-Fit.txt","SUCCESS: corrected weapon-shop proportions. Sign mapped at native image aspect and fitted to the remaining header height above the level shop floor, with continuous surrounding fascia. Central glazing and four variant bays use aspect-correct centered crops instead of image stretching. Upper hospital glass wraps at4.8745m per two-floor image with horizontal crop matching physical aspect; original structural positions retained. Top soffit, two end returns and bottom sealed to remove open storefront-to-wall edges. One existing material/atlas and one submesh perLOD retained; original atlas pixels and other buildings untouched (no texture/material/shader edits this pass). Measured pavement drop="+(maxGround-minGround)+"m; level shop floor="+floorLevel+"m; entrance riser="+rise+"m. Existing-shop glazing and door shifted together above the level landing, preserving their scale. New step/skirt follows pavement, three simple access box colliders. Summed triangles="+total+" across3LODs. Temporary1.8m reference removed before save. Shader errors=0.");}
